class Task:
    def __init__(self, C_i, T_i, id_i):
        self.C = C_i  # Worst-Case Execution Time
        self.T = T_i  # Period
        self.id = id_i # Task identifier

def create_task_set(task_data_list):
    task_set = []
    for i, (C, T) in enumerate(task_data_list):
        task_set.append(Task(C, T, i + 1))
    return task_set

def sort_tasks_by_period(task_set):
    task_set.sort(key=lambda task: task.T)
    for i, task in enumerate(task_set):
        task.id = i + 1 # Re-index after sorting
    return task_set

def calculate_period_ratios(task_set):
    k_ratios = {}
    for i in range(1, len(task_set)): # Start from the second task
        tau_i = task_set[i]
        tau_i_minus_1 = task_set[i-1]
        k_i = tau_i.T / tau_i_minus_1.T
        k_ratios[tau_i.id] = k_i
    return k_ratios

def calculate_K_min(task_set):
    k_ratios = calculate_period_ratios(task_set) # Assumes task_set is sorted
    if not k_ratios:
        return float('inf') # Or handle error for single task
    return min(k_ratios.values())

def is_harmonic(task_set):
    k_ratios = calculate_period_ratios(task_set) # Assumes task_set is sorted
    for k_i in k_ratios.values():
        if not k_i.is_integer():
            return False
    return True

def is_loose_harmonic(task_set):
    if not task_set:
        return True
    T_1 = task_set[0].T # Assumes task_set is sorted by period
    for i in range(1, len(task_set)):
        tau_i = task_set[i]
        if (tau_i.T / T_1).is_integer() == False:
            return False
    return True

def calculate_system_utilization(task_set):
    U_total = 0.0
    for task_i in task_set:
        u_i = task_i.C / task_i.T
        U_total += u_i
    return U_total

import math

def calculate_lcm(numbers):
    if not numbers:
        return 1
    result = numbers[0]
    for i in range(1, len(numbers)):
        result = (result * numbers[i]) // math.gcd(result, numbers[i])
    return result

def calculate_hyperperiod(task_set):
    periods = [task.T for task in task_set]
    return calculate_lcm(periods)

def calculate_rbf(task_i, t, task_set_sorted_by_priority):
    rbf_i_t = task_i.C
    for task_j in task_set_sorted_by_priority:
        if task_j.id < task_i.id: # Assuming lower id means higher priority
            rbf_i_t += math.floor(t / task_j.T) * task_j.C
    return rbf_i_t

def calculate_omega_i_t(t_current, task_i_current_job, task_set):
    min_D_next = float('inf')
    for task_k in task_set:
        if task_k.id != task_i_current_job.task_id:
            D_next_k = calculate_D_next_k_t(t_current, task_k)
            if D_next_k < min_D_next:
                min_D_next = D_next_k
    return min_D_next

def calculate_L_p_t_recursive(t_current, sorted_future_tasks):
    if not sorted_future_tasks:
        return {}

    L_times = {}
    # Base case: last job in the sorted list
    last_task = sorted_future_tasks[-1]
    L_times[last_task.id] = calculate_L_m_t(last_task, t_current)

    # Recursive step: work backward
    for i in range(len(sorted_future_tasks) - 2, -1, -1):
        current_task = sorted_future_tasks[i]
        next_task = sorted_future_tasks[i+1]

        D_next_p = calculate_D_next_k_t(t_current, current_task)
        L_p_plus_1 = L_times[next_task.id]

        L_times[current_task.id] = min(D_next_p, L_p_plus_1) - current_task.C

    return L_times
